}

.btn-clear:hover {
    background: #eee;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 8px;
    border: 1px solid #e0e0e0;
    margin-bottom: 1.5rem;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.sort-control {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.sort-control label {
    font-weight: 600;
    font-size: 0.9rem;
    color: #555;
}

.sort-control select {
    padding: 0.4rem 0.6rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
    background: #fff;
}

.results-summary {
    font-size: 0.9rem;
    color: #666;
}

.catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.4rem;
    margin-top: 2rem;
    flex-wrap: wrap;
}

.page-btn {
    padding: 0.4rem 0.8rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    background: #fff;
    cursor: pointer;
    font-size: 0.9rem;
    transition: background 0.2s;
}

.page-btn:hover:not(:disabled):not(.active) {
    background: #e9ecef;
}

.page-btn.active {
    background: #2a7ae2;
    color: #fff;
    border-color: #2a7ae2;
}

.page-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

