arguments.file_text:
@page "/catalog"
@using sv_45e27114900349e5b12bab2ab2c260df.Components.Catalog
@using sv_45e27114900349e5b12bab2ab2c260df.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<h1>Product Catalog</h1>

@if (_error is not null)
{
    <div class="catalog-error">
        <p>Something went wrong loading products.</p>
        <p>@_error</p>
        <button @onclick="RetryLoad">Try Again</button>
    </div>
}
else
{
    <div class="catalog-layout">
        <aside class="catalog-sidebar">
            <CatalogFilters Categories="_categories"
                            OnApplyFilters="HandleApplyFilters"
                            OnClearFilters="HandleClearFilters" />
        </aside>

        <main class="catalog-main">
            @if (_loading)
            {
                <div class="catalog-loading">
                    <p>Loading products…</p>
                </div>
            }
            else if (_result is null || _result.Items.Count == 0)
            {
                <div class="catalog-empty">
                    <p>No products found matching your criteria.</p>
                </div>
            }
            else
            {
                <CatalogToolbar SortBy="@_sortBy"
                                Page="_currentPage"
                                PageSize="@PageSize"
                                TotalCount="_result.TotalCount"
                                OnSortChanged="HandleSortChanged" />

                <ProductGrid Products="_result.Items"
                             OnProductSelected="HandleProductSelected"
                             OnAddToCart="HandleAddToCart" />

                @if (TotalPages > 1)
                {
                    <CatalogPagination CurrentPage="_currentPage"
                                       TotalPages="TotalPages"
                                       OnPageChanged="HandlePageChanged" />
                }
            }
        </main>
    </div>
}

@code {
    private const int PageSize = 12;

    private List<string> _categories = [];
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private bool _loading = true;
    private string? _error;

    /// <summary>Raised when a product card is clicked (not the Add to Cart button).</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private int TotalPages =>
        _result is null ? 0 : (int)Math.Ceiling((double)_result.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            StateHasChanged();

            _categories = await ProductService.GetCategoriesAsync();
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task SearchAsync()
    {
        try
        {
            _loading = true;
            _error = null;
            StateHasChanged();

            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleClearFilters()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await SearchAsync();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await SearchAsync();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder — wire up to a cart service when available
        return Task.CompletedTask;
    }

    private async Task RetryLoad()
    {
        _currentPage = 1;
        await LoadDataAsync();
    }
}

.catalog-layout {
    display: flex;
    gap: 2rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    min-width: 220px;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-loading,
.catalog-empty,
.catalog-error {
    text-align: center;
    padding: 3rem 1rem;
    color: #666;
}

.catalog-error {
    background: #fff5f5;
    border: 1px solid #dc3545;
    border-radius: 8px;
    color: #dc3545;
}

.catalog-error button {
    margin-top: 1rem;
    padding: 0.5rem 1.5rem;
    background: #dc3545;
    color: #fff;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-weight: 600;
}

.catalog-error button:hover {
    background: #b52d3a;
}

